  state.spirit.stage += 1;
  syncCultivation();
  maybeUnlockBody();
  notify(`Spirit cultivation · ${spiritTitle()} reached.`, 'breakthrough');
  showToast(`Qi refines into a deeper stage · ${spiritTitle()}.`);
  save(); render();
}

