import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = readFileSync(join(runtime, 'linux.json'), 'utf8');
const cfg = JSON.parse(config);

const URL = process.env.TEST_URL || 'http://127.0.0.1:4173/';
const KEY = 'stillwater-cultivator-v1';
let failures = 0;
const check = (label, ok, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'} · ${label}${detail ? ` · ${detail}` : ''}`);
  if (!ok) failures++;
};

const base = (over = {}) => ({
  version: 4,
  qi: 1000,
  stones: 100,
  spirit: { realm: 0, stage: 0, breaks: 0, criticals: 0, failures: 0, bonuses: { qi: 0, spell: 0, dao: 0 } },
  body: { realm: 0, stage: 0, unlocked: false, breaks: 0, criticals: 0, failures: 0, bonuses: { hp: 0, attack: 0, guard: 0 } },
  ...over,
});

const browser = await chromium.launch({ headless: true });
const results = [];

async function open(save, random = null) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  page.on('pageerror', e => { console.log('PAGE ERROR ·', e.message); failures++; });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE ERROR ·', m.text()); });
  await page.addInitScript(([k, v, r]) => {
    localStorage.setItem(k, v);
    if (r !== null) Math.random = () => r;
  }, [KEY, JSON.stringify(save), random]);
  await page.goto(URL, { waitUntil: 'load' });
  await page.waitForTimeout(350);
  const stored = await page.evaluate(k => JSON.parse(localStorage.getItem(k)), KEY);
  results.push({ page, context, stored });
  return results[results.length - 1];
}
const storedNow = async page => page.evaluate(k => JSON.parse(localStorage.getItem(k)), KEY);

// 1. Fresh state / Paths removed
{
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  page.on('pageerror', e => { console.log('PAGE ERROR ·', e.message); failures++; });
  await page.goto(URL, { waitUntil: 'load' });
  await page.waitForTimeout(350);
  check('fresh realm is Mortal', (await page.locator('#realmName').textContent()).trim() === 'Mortal');
  check('fresh stage badge has no stage', (await page.locator('#stageBadge').textContent()).trim() === '凡人');
  check('Paths nav removed', await page.locator('[data-view="paths"]').count() === 0);
  check('Paths view removed', await page.locator('#view-paths').count() === 0);
  check('body card is sealed', (await page.locator('#dualCultivation').textContent()).includes('Body Path Sealed'));
  await context.close();
}

// 2. Mortal awakening
{
  const { page, context } = await open(base({ qi: 500 }));
  const before = (await storedNow(page)).qi;
  await page.locator('[data-action="advance-spirit"]').click();
  await page.waitForTimeout(300);
  const s = await storedNow(page);
  check('awakening reaches Qi Condensation I', s.spirit.realm === 1 && s.spirit.stage === 0);
  check('awakening spends 120 qi', before - s.qi >= 120 && before - s.qi <= 121, `spent ${before - s.qi}`);
  check('awakening title rendered', (await page.locator('#realmName').textContent()).trim() === 'Qi Condensation I');
  await context.close();
}

// 3. Independent body stage advance with shared qi
{
  const { page, context } = await open(base({ qi: 5000, spirit: { realm: 3, stage: 0, breaks: 2, criticals: 0, failures: 0, bonuses: { qi: 2, spell: 2, dao: 2 } }, body: { realm: 0, stage: 0, unlocked: true, breaks: 0, criticals: 0, failures: 0, bonuses: { hp: 0, attack: 0, guard: 0 } } }));
  const before = (await storedNow(page)).qi;
  await page.locator('[data-action="advance-body"]').click();
  await page.waitForTimeout(300);
  const s = await storedNow(page);
  check('body advances independently', s.body.stage === 1 && s.spirit.realm === 3);
  check('body stage spends 90 qi', before - s.qi >= 90 && before - s.qi <= 91, `spent ${before - s.qi}`);
  check('body title rendered Mortal Body II', (await page.locator('#dualCultivation').textContent()).includes('Mortal Body II'));
  await context.close();
}

// 4. Body unlocks at Golden Core I
{
  const { page, context } = await open(base({ qi: 1e9, spirit: { realm: 2, stage: 9, breaks: 1, criticals: 0, failures: 0, bonuses: { qi: 1, spell: 1, dao: 1 } } }), 0);
  await page.locator('[data-action="open-spirit-break"]').first().click();
  await page.waitForTimeout(120);
  check('spirit breakthrough modal opens at stage X', (await page.locator('.modal').count()) > 0);
  await page.locator('[data-action="attempt-spirit-break"]').click();
  await page.waitForTimeout(300);
  const s = await storedNow(page);
  check('spirit reaches Golden Core I', s.spirit.realm === 3 && s.spirit.stage === 0);
  check('body unlocks at Golden Core I', s.body.unlocked === true);
  await context.close();
}

// 5. Failed breakthrough remains at stage X and loses 10% qi
{
  const { page, context } = await open(base({ qi: 1000000, spirit: { realm: 4, stage: 9, breaks: 2, criticals: 0, failures: 0, bonuses: { qi: 2, spell: 2, dao: 2 } }, body: { realm: 0, stage: 0, unlocked: true, breaks: 0, criticals: 0, failures: 0, bonuses: { hp: 0, attack: 0, guard: 0 } } }), 0.999);
  await page.locator('[data-action="open-spirit-break"]').first().click();
  await page.locator('[data-action="attempt-spirit-break"]').click();
  await page.waitForTimeout(300);
  const s = await storedNow(page);
  check('failed spirit breakthrough stays at stage X', s.spirit.realm === 4 && s.spirit.stage === 9);
  check('failure records and scatters ~10% qi', s.spirit.failures === 1 && s.qi < 910000 && s.qi > 890000, `qi ${s.qi}`);
  check('failure toast shown', (await page.locator('#toast').textContent()).includes('The tribulation resists'));
  await context.close();
}

// 6. Critical body breakthrough reward
{
  const { page, context } = await open(base({ qi: 1e9, spirit: { realm: 3, stage: 0, breaks: 2, criticals: 0, failures: 0, bonuses: { qi: 2, spell: 2, dao: 2 } }, body: { realm: 0, stage: 9, unlocked: true, breaks: 0, criticals: 0, failures: 0, bonuses: { hp: 0, attack: 0, guard: 0 } } }), 0);
  await page.locator('[data-action="open-body-break"]').first().click();
  await page.waitForTimeout(120);
  check('body breakthrough modal opens at stage X', (await page.locator('.modal').count()) > 0);
  await page.locator('[data-action="attempt-body-break"]').click();
  await page.waitForTimeout(300);
  const s = await storedNow(page);
  check('critical body breakthrough reaches Skin Tempering I', s.body.realm === 1 && s.body.stage === 0);
  check('critical body reward doubled', s.body.criticals === 1 && s.body.bonuses.hp === 2 && s.body.bonuses.attack === 2 && s.body.bonuses.guard === 2);
  await context.close();
}

// 7. Legacy v3 save migration
{
  const legacy = base({ version: 3, qi: 100, stage: 10, spirit: { realm: 1, stage: 4, breaks: 0, criticals: 0, failures: 0, bonuses: { qi: 0, spell: 0, dao: 0 } }, body: { realm: 0, stage: 0, unlocked: false, breaks: 0, criticals: 0, failures: 0, bonuses: { hp: 0, attack: 0, guard: 0 } }, pathLevels: { body: 5, spirit: 5, qi: 5 } });
  const { page, context } = await open(legacy);
  const s = await storedNow(page);
  check('legacy spirit realm shifted by one', s.spirit.realm === 2 && s.spirit.stage === 4, `realm ${s.spirit.realm} stage ${s.spirit.stage}`);
  check('legacy save normalized to version 4', s.version === 4);
  check('legacy path ranks removed', s.pathLevels === undefined);
  await context.close();
}

await browser.close();
console.log(`\n${failures === 0 ? 'ALL CHECKS PASSED' : `${failures} CHECK(S) FAILED`}`);
process.exit(failures === 0 ? 0 : 1);

